"""CPU replay of the final public launcher, actual package switch and wrong-power refusal."""
import argparse,hashlib,io,json,zipfile
from pathlib import Path
import numpy as np
from kernel_agent.protocol import decode_frame
from kernel_agent.bounded_io import confirmed_removed
ROOT=Path(__file__).resolve().parents[2]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def audit(folder):
 a=folder/'segmented-archive';r=a/'remote';e=json.loads((a/'execution.json').read_text());assert sha(a/'raw.zip')==json.loads((a/'collection.json').read_text())['archive_sha256'];assert all(sha(r/n)==m['sha256'] and (r/n).stat().st_size==m['bytes'] for n,m in e['manifest'].items());v=json.loads((r/'activation/result.json').read_text());assert v['status']=='ACTIVE_ENTRY_PASS' and v['production_release'] is True and v['gpu_outputs']==v['gpu_attempts']==3 and v['actual_package_switch_pass'] and v['power_restored_watts']==170;assert sha(r/'tools/cdi_container_entry.py')==v['launcher_source_sha256']==sha(ROOT/'tools/cdi_container_entry.py');x=np.load(r/'workspace/a.npy',allow_pickle=False);y=np.load(r/'workspace/b.npy',allow_pickle=False);reference=x.astype(np.float64)@y.astype(np.float64);assert np.array_equal(reference,np.load(r/'workspace/reference.npy',allow_pickle=False));outputs=json.loads((r/'activation/outputs.json').read_text());assert {o['label'] for o in outputs}=={'qualified-default','package-preview','package-restored'};count=0
 for o in outputs:
  ex=o['execution'];assert ex['status']=='PASS' and ex['production_release'] is (o['label']!='package-preview') and not ex['fallback_used'] and not ex['promotion_performed'] and len(ex['attempts'])==1;job=r/Path(ex['run_directory']).relative_to(e['remote_root'])/'attempt-0';record=json.loads((job/'record.json').read_text());assert record['status']=='OUTPUT_VALID' and record['exit']==0 and record['reason'] is None and record['cleanup']['removed'] and confirmed_removed(record['cleanup']['inspect_after_cleanup']) and record['protected_files_unchanged'];assert all(sha(job/n)==h for n,h in record['protected_sha256'].items());cmd=record['command'];assert '--runtime=runc' in cmd and cmd[cmd.index('--device')+1]=='nvidia.com/gpu=0' and cmd[cmd.index('--user')+1]=='65534:65534' and '--network=none' in cmd and '--cap-drop=ALL' in cmd and '--security-opt=no-new-privileges' in cmd and cmd.count('--mount')==2 and all('readonly' in cmd[i+1] for i,c in enumerate(cmd) if c=='--mount');meta,payload=decode_frame(job/'capture/stdout.bin',x.shape[0]*y.shape[1]*4+16384);assert meta==record['metadata'] and meta['uid']==65534 and payload==(job/'result.npy').read_bytes();actual=np.load(io.BytesIO(payload),allow_pickle=False);assert actual.dtype==np.float32 and np.isfinite(actual).all() and np.all(np.abs(actual-reference)<=3e-5+1e-4*np.abs(reference)) and np.array_equal(actual,np.load(r/'workspace'/(o['label']+'.npy'),allow_pickle=False));count+=1
 commands=json.loads((r/'activation/commands.json').read_text());negative=next(c for c in commands if c['label']=='wrong-power-rejected');assert negative['exit']!=0 and 'requires170W' in (r/'activation/wrong-power-rejected.stderr').read_text();power=json.loads((r/'activation/power-control.json').read_text());assert [c['watts'] for c in power]==[160,170] and all(c['exit']==0 for c in power)
 traces=[json.loads(p.read_text()) for p in (r/'launcher-records').glob('*.json')];init_hash={}
 for version in ['0.1.3rc2','0.1.3']:
  with zipfile.ZipFile(ROOT/'artifacts/wheels'/('nvidia_kernel_agent-'+version+'-py3-none-any.whl')) as z:init_hash[version]=hashlib.sha256(z.read('kernel_agent/__init__.py')).hexdigest()
 assert any(t['package_init_sha256']==init_hash['0.1.3rc2'] and t['exit']==0 for t in traces) and any(t['package_init_sha256']==init_hash['0.1.3'] and t['exit']==0 for t in traces)
 for t in traces:
  cmd=t['command'];assert '--network=none' in cmd and '--runtime=runc' in cmd and '--device' in cmd and 'NVIDIA_VISIBLE_DEVICES=void' in cmd and '--security-opt=no-new-privileges' in cmd and any('readonly' in cmd[i+1] and t['prefix'] in cmd[i+1] for i,c in enumerate(cmd) if c=='--mount')
 result={'status':'AUDIT_PASS_ACTIVE_ENTRY','raw_files_verified':len(e['manifest']),'gpu_outputs':count,'gpu_attempts':count,'actual_package_switch_pass':True,'actual_wrong_power_rejection_pass':True,'power_restored_watts':170,'launcher_source_sha256':v['launcher_source_sha256'],'new_model_calls':0,'new_event_samples':0,'production_release':True};(folder/'verification.json').write_text(json.dumps(result,indent=2));return result
